"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[9075],{6746(t){t.exports=JSON.parse('{"tag":{"label":"Big-O","permalink":"/concepts/tags/big-o","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"foundations-of-algorithms/asymptotic-notation","title":"Asymptotic Notation","description":"In the previous lesson we obtained exact expressions such as $T(n) = 3n + 4$ and saw that the constants depend on arbitrary counting decisions and, in reality, on the machine. What does not depend on them is the rate of growth of the function: how fast $T(n)$ increases when $n$ becomes large.","permalink":"/concepts/foundations-of-algorithms/asymptotic-notation"},{"id":"foundations-of-algorithms/case-study-pairwise","title":"Case Study - Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimisations\\" that are not actually correct.","permalink":"/concepts/foundations-of-algorithms/case-study-pairwise"}],"unlisted":false}}')}}]);